using System.Collections;
using System.Collections.Generic;
using UnityEngine;
using Cinemachine;

// Generated by Claude :)

[RequireComponent(typeof(CinemachineImpulseSource))]
public class ScreenShakeManager : GenericSingleton<ScreenShakeManager>
{
    private CinemachineImpulseSource src;

    [SerializeField]
    private Vector3 randVelocityLow;
    [SerializeField]
    private Vector3 randVelocityHigh;

    [Header("Damping / Limiting")]
    [Tooltip("Hard cap on force passed to GenerateImpulse, regardless of what's requested.")]
    [SerializeField]
    private float maxForce = 0.5f;

    [Tooltip("Minimum time (seconds) between shakes at full strength. Calls within this window get scaled down.")]
    [SerializeField]
    private float cooldownTime = 0.3f;

    [Tooltip("If a shake comes in before cooldown has elapsed, multiply its force by this per 'stacked' call (extra safety on top of cooldown scaling).")]
    [SerializeField]
    [Range(0f, 1f)]
    private float stackDamping = 0.5f;

    private float lastShakeTime = -999f;

    [Header("Uncomment the Update->check keycode block in this script to debug")]
    [SerializeField]
    private float debugForce;

    void Start()
    {
        src = GetComponent<CinemachineImpulseSource>();
    }

    // TODO: create custom editor to allow for screenshake debugging
    /*
    void Update()
    {
        if (Input.GetKeyDown(KeyCode.I))
        {
            ShakeWithForce(debugForce);
        }
    }
    */

    public void ShakeWithForce(float force)
    {
        float now = Time.time;
        float timeSinceLast = now - lastShakeTime;

        // Clamp the incoming force first
        force = Mathf.Min(force, maxForce);

        // If we're still within the cooldown window, damp the force
        // proportionally to how "fresh" the last shake still is.
        if (timeSinceLast < cooldownTime)
        {
            float freshness = 1f - (timeSinceLast / cooldownTime); // 1 = just shook, 0 = cooldown over
            float damp = Mathf.Lerp(1f, stackDamping, freshness);
            force *= damp;
        }

        lastShakeTime = now;

        src.m_DefaultVelocity = new Vector3(
            Random.Range(randVelocityLow.x, randVelocityHigh.x),
            Random.Range(randVelocityLow.y, randVelocityHigh.y),
            Random.Range(randVelocityLow.z, randVelocityHigh.z)
            );
        src.GenerateImpulse(force);
    }
}
